parameters.query:
CREATE TABLE IF NOT EXISTS obec (
    kod   integer PRIMARY KEY,
    nazev text NOT NULL
);
CREATE TABLE IF NOT EXISTS obvod_prahy (
    kod      integer PRIMARY KEY,
    nazev    text NOT NULL,
    obec_kod integer NOT NULL REFERENCES obec (kod) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS momc (
    kod             integer PRIMARY KEY,
    nazev           text NOT NULL,
    obec_kod        integer NOT NULL REFERENCES obec (kod) DEFERRABLE INITIALLY DEFERRED,
    obvod_prahy_kod integer REFERENCES obvod_prahy (kod) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS cast_obce (
    kod      integer PRIMARY KEY,
    nazev    text NOT NULL,
    obec_kod integer NOT NULL REFERENCES obec (kod) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS ulice (
    kod      integer PRIMARY KEY,
    nazev    text NOT NULL,
    obec_kod integer NOT NULL REFERENCES obec (kod) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE IF NOT EXISTS adresni_misto (
    kod                    integer PRIMARY KEY,
    obec_kod               integer NOT NULL REFERENCES obec (kod) DEFERRABLE INITIALLY DEFERRED,
    momc_kod               integer REFERENCES momc (kod) DEFERRABLE INITIALLY DEFERRED,
    obvod_prahy_kod        integer REFERENCES obvod_prahy (kod) DEFERRABLE INITIALLY DEFERRED,
    cast_obce_kod          integer NOT NULL REFERENCES cast_obce (kod) DEFERRABLE INITIALLY DEFERRED,
    ulice_kod              integer REFERENCES ulice (kod) DEFERRABLE INITIALLY DEFERRED,
    typ_so                 text NOT NULL CHECK (typ_so IN ('č.p.', 'č.ev.')),
    cislo_domovni          integer NOT NULL,
    cislo_orientacni       integer,
    znak_cisla_orientacniho text,
    psc                    char(5) NOT NULL,
    souradnice_y           numeric(12, 2),
    souradnice_x           numeric(12, 2),
    plati_od               date NOT NULL
);
CREATE INDEX IF NOT EXISTS adresni_misto_obec_idx ON adresni_misto (obec_kod);
CREATE INDEX IF NOT EXISTS adresni_misto_cast_obce_idx ON adresni_misto (cast_obce_kod);
CREATE INDEX IF NOT EXISTS adresni_misto_ulice_idx ON adresni_misto (ulice_kod);
CREATE INDEX IF NOT EXISTS adresni_misto_psc_idx ON adresni_misto (psc);
COMMENT ON TABLE obec IS 'Obec (Kód obce / Název obce)';
COMMENT ON TABLE obvod_prahy IS 'Obvod Prahy (Kód obvodu Prahy), jen Praha';
COMMENT ON TABLE momc IS 'Městský obvod / městská část (Kód MOMC), jen členěná statutární města';
COMMENT ON TABLE cast_obce IS 'Část obce';
COMMENT ON TABLE ulice IS 'Ulice (jen obce se zavedenou uliční sítí)';
COMMENT ON TABLE adresni_misto IS 'Adresní místo (Kód ADM); souřadnice v S-JTSK [m]';

CREATE EXTENSION IF NOT EXISTS unaccent;
-- lower() + unaccent(), declared IMMUTABLE so it can be used in generated columns and indexes.
CREATE OR REPLACE FUNCTION ruian_norm(text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
    RETURN public.unaccent('public.unaccent'::regdictionary, lower($1));
ALTER TABLE obec ADD COLUMN IF NOT EXISTS nazev_tsv tsvector
    GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, ruian_norm(nazev))) STORED;
ALTER TABLE obvod_prahy ADD COLUMN IF NOT EXISTS nazev_tsv tsvector
    GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, ruian_norm(nazev))) STORED;
ALTER TABLE momc ADD COLUMN IF NOT EXISTS nazev_tsv tsvector
    GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, ruian_norm(nazev))) STORED;
ALTER TABLE cast_obce ADD COLUMN IF NOT EXISTS nazev_tsv tsvector
    GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, ruian_norm(nazev))) STORED;
ALTER TABLE ulice ADD COLUMN IF NOT EXISTS nazev_tsv tsvector
    GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, ruian_norm(nazev))) STORED;
CREATE INDEX IF NOT EXISTS obec_nazev_tsv_idx ON obec USING gin (nazev_tsv);
CREATE INDEX IF NOT EXISTS obvod_prahy_nazev_tsv_idx ON obvod_prahy USING gin (nazev_tsv);
CREATE INDEX IF NOT EXISTS momc_nazev_tsv_idx ON momc USING gin (nazev_tsv);
CREATE INDEX IF NOT EXISTS cast_obce_nazev_tsv_idx ON cast_obce USING gin (nazev_tsv);
CREATE INDEX IF NOT EXISTS ulice_nazev_tsv_idx ON ulice USING gin (nazev_tsv);
-- Parent filters of the search tools.
CREATE INDEX IF NOT EXISTS cast_obce_obec_idx ON cast_obce (obec_kod);
CREATE INDEX IF NOT EXISTS ulice_obec_idx ON ulice (obec_kod);
CREATE INDEX IF NOT EXISTS adresni_misto_momc_idx ON adresni_misto (momc_kod);
CREATE INDEX IF NOT EXISTS adresni_misto_obvod_prahy_idx ON adresni_misto (obvod_prahy_kod);
-- Full-address search (tool search_address): one word set per address place with the names of its street,
-- municipality part, municipality and districts, its numbers ('704', '36', '36a') and postal code. Built with
-- the same tokenizer as the search query (ruian_norm, split on non-alphanumerics), not to_tsvector, whose
-- parser would keep '704/36' together. NULL parts are skipped (concat_ws). The n8n import fills the column
-- from its staging table and rebuilds the index after loading.
CREATE OR REPLACE FUNCTION ruian_address_words(street text, part text, municipality text, city_district text,
                                               prague_district text, building int, orientation int,
                                               letter text, psc text) RETURNS tsvector
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    RETURN array_to_tsvector(array_remove(regexp_split_to_array(
        ruian_norm(concat_ws(' ', street, part, municipality, city_district, prague_district, building::text,
                             orientation::text, orientation::text || lower(letter), psc)),
        '[^a-z0-9]+'), ''));
ALTER TABLE adresni_misto ADD COLUMN IF NOT EXISTS adresa_tsv tsvector;
CREATE INDEX IF NOT EXISTS adresni_misto_adresa_tsv_idx ON adresni_misto USING gin (adresa_tsv);
-- Position for distances (tools search_nearby, address_distances): point(y, x) in S-JTSK metres, the
-- RUIAN coordinates as they are. S-JTSK is a projection for Czechia, so `<->` between two points is the
-- straight-line distance in metres (no extension needed). NULL for the few addresses without coordinates.
-- SP-GiST serves `<@ box` (radius pre-filter) and `ORDER BY poloha <-> point` (nearest first). Adding the
-- column to a loaded table rewrites it once; the n8n import rebuilds the index after loading.
ALTER TABLE adresni_misto ADD COLUMN IF NOT EXISTS poloha point
    GENERATED ALWAYS AS (point(souradnice_y::float8, souradnice_x::float8)) STORED;
CREATE INDEX IF NOT EXISTS adresni_misto_poloha_idx ON adresni_misto USING spgist (poloha);
DROP TABLE IF EXISTS ruian_stage;
CREATE UNLOGGED TABLE ruian_stage (kod_adm text, obec_kod text, obec_nazev text, momc_kod text, momc_nazev text, obvod_prahy_kod text, obvod_prahy_nazev text, cast_obce_kod text, cast_obce_nazev text, ulice_kod text, ulice_nazev text, typ_so text, cislo_domovni text, cislo_orientacni text, znak_cisla_orientacniho text, psc text, souradnice_y text, souradnice_x text, plati_od text);

BEGIN;
TRUNCATE adresni_misto, ulice, cast_obce, momc, obvod_prahy, obec;
INSERT INTO obec (kod, nazev)
    SELECT DISTINCT ON (obec_kod::int) obec_kod::int, btrim(obec_nazev)
    FROM ruian_stage ORDER BY obec_kod::int;
INSERT INTO obvod_prahy (kod, nazev, obec_kod)
    SELECT DISTINCT ON (obvod_prahy_kod::int) obvod_prahy_kod::int, btrim(obvod_prahy_nazev), obec_kod::int
    FROM ruian_stage WHERE nullif(btrim(obvod_prahy_kod), '') IS NOT NULL ORDER BY obvod_prahy_kod::int;
INSERT INTO momc (kod, nazev, obec_kod, obvod_prahy_kod)
    SELECT DISTINCT ON (momc_kod::int) momc_kod::int, btrim(momc_nazev), obec_kod::int, nullif(btrim(obvod_prahy_kod), '')::int
    FROM ruian_stage WHERE nullif(btrim(momc_kod), '') IS NOT NULL ORDER BY momc_kod::int;
INSERT INTO cast_obce (kod, nazev, obec_kod)
    SELECT DISTINCT ON (cast_obce_kod::int) cast_obce_kod::int, btrim(cast_obce_nazev), obec_kod::int
    FROM ruian_stage ORDER BY cast_obce_kod::int;
INSERT INTO ulice (kod, nazev, obec_kod)
    SELECT DISTINCT ON (ulice_kod::int) ulice_kod::int, btrim(ulice_nazev), obec_kod::int
    FROM ruian_stage WHERE nullif(btrim(ulice_kod), '') IS NOT NULL ORDER BY ulice_kod::int;
-- The full-address and position indexes are rebuilt after the insert; maintaining them row by row is
-- much slower. The position column (poloha) is generated from the coordinates.
DROP INDEX IF EXISTS adresni_misto_adresa_tsv_idx;
DROP INDEX IF EXISTS adresni_misto_poloha_idx;
INSERT INTO adresni_misto (kod, obec_kod, momc_kod, obvod_prahy_kod, cast_obce_kod, ulice_kod, typ_so,
                           cislo_domovni, cislo_orientacni, znak_cisla_orientacniho, psc,
                           souradnice_y, souradnice_x, plati_od, adresa_tsv)
    SELECT kod_adm::int, obec_kod::int, nullif(btrim(momc_kod), '')::int, nullif(btrim(obvod_prahy_kod), '')::int, cast_obce_kod::int,
           nullif(btrim(ulice_kod), '')::int, btrim(typ_so), cislo_domovni::int, nullif(btrim(cislo_orientacni), '')::int,
           nullif(btrim(znak_cisla_orientacniho), ''), btrim(psc), nullif(btrim(souradnice_y), '')::numeric, nullif(btrim(souradnice_x), '')::numeric,
           nullif(btrim(plati_od), '')::timestamp::date,
           ruian_address_words(nullif(btrim(ulice_nazev), ''), nullif(btrim(cast_obce_nazev), ''), nullif(btrim(obec_nazev), ''), nullif(btrim(momc_nazev), ''),
                               nullif(btrim(obvod_prahy_nazev), ''), cislo_domovni::int, nullif(btrim(cislo_orientacni), '')::int,
                               nullif(btrim(znak_cisla_orientacniho), ''), btrim(psc))
    FROM ruian_stage;
-- Run the deferred foreign-key checks now (all parents are loaded): CREATE INDEX refuses a table with
-- pending trigger events.
SET CONSTRAINTS ALL IMMEDIATE;
CREATE INDEX adresni_misto_adresa_tsv_idx ON adresni_misto USING gin (adresa_tsv);
CREATE INDEX adresni_misto_poloha_idx ON adresni_misto USING spgist (poloha);
DROP TABLE ruian_stage;
COMMIT;
ANALYZE;
SELECT (SELECT count(*) FROM obec) AS obec, (SELECT count(*) FROM obvod_prahy) AS obvod_prahy,
       (SELECT count(*) FROM momc) AS momc, (SELECT count(*) FROM cast_obce) AS cast_obce,
       (SELECT count(*) FROM ulice) AS ulice, (SELECT count(*) FROM adresni_misto) AS adresni_misto;
